nsitions -> /services", "Bulk orders minimum 500'' of material -> /services", "Materials: galvanized, galvalume, painted (Berridge, McElroy), bonderized, stainless steel, copper -> /services", "Industries: residential, commercial, roofing, waterproofing, custom builders, homeowners -> /services, /", "Precision down to 1/16 inch -> / (review)", "Fast turnaround, no middlemen -> /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Stuart''s Sheet Metal in Austin, can custom fabricate a wide range of products to fit your specific job requirements.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "Minimum of 500'' of material for bulk orders", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='stuart-s-sheet-metal' AND approved AND profile IS NULL;
UPDATE companies SET description='Studio Wise is a furniture manufacturer based in Grand Rapids, Michigan. The company develops and produces purposeful furniture collections designed to help clients tell a story in any space.

