UPDATE companies SET description='Sun Tech Industries Inc was founded in 1998 in Ravenna, Nebraska, as a locally owned and operated custom plastic injection molding company. From the start, the business built its reputation on meeting and exceeding customer requirements through consistent precision and dedicated attention to fulfilling customer needs.

The company specializes in custom plastic injection molding and offers value-added services designed to reduce customer costs. Its production floor uses advanced automation, including robots, and runs lights-out operations when needed. Quality is maintained by experienced mold processing and maintenance technicians with over 100 years of combined experience, continually trained machine operators, and a preventative maintenance program that maximizes tooling and equipment life.

Its customer attention emphasizes superior lead times, timeliness in delivery, and flexibility to adjust needs during production.

The company''s quality program is based on ISO 9001:2015, with a company-wide commitment to go beyond requirements. Traceability is maintained at each step from raw material receipt through shipment, using date stamps on box labels and date codes on tools. Inspection covers part characteristics during production runs, and all measuring equipment is calibrated to standards traceable to national or international benchmarks.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Custom plastic injection molding", "Value-added services", "Automated injection molding with robots", "Lights-out manufacturing", "Mold processing and maintenance", "Preventative maintenance program", "Part approval (PPAP, master sample sign-off)", "Traceability management", "Inspection and certification (raw material certs, data sheets, MSDS)", "Calibration and measurement verification", "Nonconforming product control"], "industries": [], "materials": [], "equipment": ["Robots", "Automation equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Advanced automation including robots and lights-out operation", "Quality program based on ISO 9001:2015", "Over 100 years combined experience among mold technicians", "Full traceability from raw material to shipment", "Flexible production adjustments during runs"], "facts_used": ["Founded in 1998 -> /about-us", "Located in Ravenna, NE -> /about-us", "Locally owned and operated -> /about-us", "Custom plastic injection molding company -> /about-us", "Value-added services reduce customer costs -> /", "Advanced automation including robots -> /", "Lights-out operation -> /", "Quality program based on ISO 9001:2015 -> /quality", "Over 100 years combined experience among technicians -> /quality", "Continually trained machine operators -> /quality", "Preventative maintenance program -> /quality", "Part approval processes (PPAP, master sample) -> /quality", "Traceability each step from raw material to shipment -> /quality", "Date stamps on box labels and date codes on tools -> /quality", "Inspection during production runs, raw material certs maintained -> /quality", "Measuring equipment calibrated to national/international standards -> /quality", "Nonconforming product procedure -> /quality", "Superior lead times, timeliness in delivery, flexible adjustments -> /about-us", "Focus on dependability in products, quality, delivery -> /about-us"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "we are a locally owned and operated custom plastic injection molding company", "founded_year": "1998", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='sun-tech-industries-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='SunPower Corporation was founded in 1985 and is headquartered in San Jose, California. The company designs and manufactures high-efficiency monocrystalline solar panels and provides complete solar power systems for residential, commercial, and utility applications.

