UPDATE companies SET description='Surface Mount Depot, now operating as SMD, was founded in 1988 in Oklahoma City, Oklahoma. The company began as a contract electronics manufacturer focused on printed circuit board assembly and has since expanded into a full-service provider for high-reliability applications.

SMD delivers a range of electronics manufacturing services including surface mount and through-hole PCB assembly, cable and wire harness assembly, electromechanical and box-build assembly, hand soldering, functional testing, and engineering support. The facility employs automated placement equipment, wave and selective wave soldering, and advanced inspection systems to handle projects from prototype through production.

Its client base includes organizations requiring ITAR-compliant production and long-term supply partnerships.

SMD differentiates itself through an ISO 9001 certification held for over two decades, ITAR compliance, and a commitment to personalized service that assigns the same point of contact throughout a project. The company emphasizes competitive pricing, on-time delivery, and a stable workforce with many employees remaining since inception.', certifications=ARRAY['ISO 9001','ITAR']::text[], profile='{"capabilities": ["Surface mount assembly", "Through-hole assembly", "Wave soldering", "Selective wave soldering", "Hand soldering", "Cable and wire harness assembly", "Electromechanical assembly", "Box build assembly", "Functional testing", "Automated component placement", "Advanced inspection", "Engineering support", "Value-added services"], "industries": ["Industrial", "High-reliability electronics"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ISO 9001 certified for over 20 years", "ITAR compliant", "Consistent point of contact for each project", "Competitive pricing and on-time delivery", "Stable, long-tenured workforce"], "facts_used": ["Founded in 1988 -> /about", "Headquarters in Oklahoma City, Oklahoma -> db", "ISO 9001 certification held for over two decades -> /about", "ITAR compliant -> /about", "Services: surface mount assembly, through-hole assembly, cable/wire harness assembly, electromechanical assembly, hand soldering, testing, engineering support -> /services", "Automated placement and advanced inspection equipment -> /services", "Competitive pricing and on-time delivery emphasis -> /", "Personalized customer service with consistent point of contact -> /about", "Many employees since inception -> /about"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "SMD, formerly known as Surface Mount Depot, is one of the leading electronics contract manufacturers in the United States.", "founded_year": "1988", "employee_count": "", "cage_code": "", "min_order": "", "expor